import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("export pools", () => {
  test("export pools", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_lee_jo = ui.must(await ui.addPerson(pg_uma, {"name": "Lee, Jo", "grade": "B"}));
    await ui.setSetting(pg_uma, "pot", "10.00");
    expect(await ui.addPool(pg_uma, "P1")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.33"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Lee, Jo", "share": "66.67"})).toBe(true);
    expect(await ui.addPool(pg_uma, "Q")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "Q", {"member": "pool:P1", "share": "100.00"})).toBe(true);
    expect(await ui.exportPools(pg_uma)).toBe("pool,member,share,cut\nP1,Ada,33.33,3.33\nP1,\"Lee, Jo\",66.67,6.67\nQ,pool:P1,100.00,10.00\n");
    expect(await ui.retire(pg_uma, p_ada, "2026-03-01")).toBe(true);
    expect(await ui.exportPools(pg_uma)).toBe("pool,member,share,cut\nP1,Ada,33.33,0.00\nP1,\"Lee, Jo\",66.67,10.00\nQ,pool:P1,100.00,10.00\n");
  });
  test("export pools scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    await ui.setSetting(pg_uma, "floor", "0.50");
